"""Measure figure text collisions, label regions and container centering."""
from pathlib import Path
import json
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1];O=R/'e-book/exports/v19'
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);q=b.new_page(viewport={'width':1200,'height':900});q.goto((O/'ebook_review_v19.html').as_uri());q.evaluate('document.fonts.ready')
 rows=q.evaluate('''()=>[...document.querySelectorAll('figure[data-figure]')].map(f=>{const svg=f.querySelector('svg'),rr=f.getBoundingClientRect(),pr=f.parentElement.getBoundingClientRect();let ts=[...svg.querySelectorAll('text')],collisions=[],regions=[];for(let i=0;i<ts.length;i++){let a=ts[i].getBoundingClientRect();if(ts[i].dataset.region){let [x,y,w,h]=JSON.parse(ts[i].dataset.region),z=ts[i].getBBox();if(z.x<x-1||z.y<y-1||z.x+z.width>x+w+1||z.y+z.height>y+h+1)regions.push(ts[i].textContent)}for(let j=i+1;j<ts.length;j++){let bb=ts[j].getBoundingClientRect(),ix=Math.min(a.right,bb.right)-Math.max(a.left,bb.left),iy=Math.min(a.bottom,bb.bottom)-Math.max(a.top,bb.top);if(ix>1&&iy>1)collisions.push([ts[i].textContent,ts[j].textContent])}}return {file:f.dataset.figure,centering_error_css_px:Math.abs((rr.left+rr.right-pr.left-pr.right)/2),text_collisions:collisions,outside_intended_regions:regions}})''');cover=q.evaluate('''()=>{let s=document.querySelector('.cover svg'),ts=[...s.querySelectorAll('text')],bad=[];for(let i=0;i<ts.length;i++){let a=ts[i].getBBox();if(a.x<0||a.y<0||a.x+a.width>s.viewBox.baseVal.width||a.y+a.height>s.viewBox.baseVal.height)bad.push(['outside',ts[i].textContent]);let aa=ts[i].getBoundingClientRect();for(let j=i+1;j<ts.length;j++){let bb=ts[j].getBoundingClientRect();if(Math.min(aa.right,bb.right)-Math.max(aa.left,bb.left)>1&&Math.min(aa.bottom,bb.bottom)-Math.max(aa.top,bb.top)>1)bad.push(['overlap',ts[i].textContent,ts[j].textContent])}}return {title:s.querySelector('title').textContent,text_issues:bad}}''');out=R/'e-book/design/v19/review';out.mkdir(parents=True,exist_ok=True)
 for name in ['winner_effect.svg','guardrail_effect.svg','measurement_v06.svg','segments_v06.svg','capacity_v06.svg']:q.locator('figure[data-figure="'+name+'"]').screenshot(path=str(out/(name+'.png')))
 q.locator('.cover').screenshot(path=str(out/'cover.png'));b.close()
report={'scope':'Actual browser text boxes; conceptual labels additionally checked against declared panels. Not a reader study or a complete accessibility audit.','cover':cover,'figures':rows,'issues':[r for r in rows if r['centering_error_css_px']>.6 or r['text_collisions'] or r['outside_intended_regions']]}
(O/'visual_geometry_v19.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8',newline='\n');print(json.dumps(report,ensure_ascii=False,indent=2));assert not report['issues'] and not cover['text_issues']
